 List<InventoryLineK> InventoryLinesK(DesktopWindow w,bool hangar){var result=new List<InventoryLineK>();foreach(string id in world.InventoryDisplayIds(hangar).Where(id=>world.InventoryDisplayCount(id,hangar)>.001m)){if(!world.InventoryDisplayName(id).Contains(w.QueryJ,StringComparison.OrdinalIgnoreCase))continue;if(w.HoldK.Length>0&&!hangar){string category=world.InventoryMission(id) is {} m?m.Spec.Division==AgentDivision38.Mining?m.Spec.Resource:"mission-freight":id;if(!DemoWorld.HoldAccepts(w.HoldK,category))continue;}string key=(hangar?world.StationKey44:world.Player.InstanceId)+"/"+id;var portions=StackPresentationK.Reconcile(world.InventoryDisplayCount(id,hangar),w.SplitStacksK.GetValueOrDefault(key));w.SplitStacksK[key]=portions;for(int i=0;i<portions.Count;i++)result.Add(new(id,portions[i],i));}return result;}
 void SelectInventoryK(DesktopWindow w,InventoryHit hit,KeyboardState keys){bool control=keys.IsKeyDown(Keys.LeftControl)||keys.IsKeyDown(Keys.RightControl),shift=keys.IsKeyDown(Keys.LeftShift)||keys.IsKeyDown(Keys.RightShift);if(control){if(!w.SelectionK.Add(hit.KeyK))w.SelectionK.Remove(hit.KeyK);}else if(shift){var visible=itemHits.Where(h=>h.Owner==w.Owner).ToList();int start=visible.FindIndex(h=>w.SelectionK.Contains(h.KeyK)),end=visible.IndexOf(hit);if(start>=0&&end>=0)foreach(var row in visible.Skip(Math.Min(start,end)).Take(Math.Abs(start-end)+1))w.SelectionK.Add(row.KeyK);else w.SelectionK.Add(hit.KeyK);}else if(!w.SelectionK.Contains(hit.KeyK)){w.SelectionK.Clear();w.SelectionK.Add(hit.KeyK);}SaveDesktop();}
 void InventoryMenuExtrasK(InventoryHit hit,List<(string,Action)> actions){var w=desktop.FirstOrDefault(w=>w.Owner==hit.Owner);if(w==null)return;actions.Add(("Move selected stacks",()=>TransferSelectionK(w,hit.Hangar)));if(hit.QuantityK>1||world.InventoryMission(hit.Id)!=null){actions.Add(("Split stack...",()=>{quantityItemK=hit;quantityEditK.Set((hit.QuantityK/2).ToString("0.##",System.Globalization.CultureInfo.InvariantCulture));quantityFocusK=true;quantityErrorK="";context=false;editJ.Focus=false;}));}actions.Add(("Stack all",()=>{foreach(var key in w.SplitStacksK.Keys.ToArray())w.SplitStacksK[key]=[w.SplitStacksK[key].Sum()];w.SelectionK.Clear();SaveDesktop();}));actions.Add(("Select all visible stacks",()=>{w.SelectionK=InventoryLinesK(w,hit.Hangar).Select(l=>l.Key).ToHashSet();SaveDesktop();}));}
 void TransferSelectionK(DesktopWindow w,bool fromHangar){var lines=InventoryLinesK(w,fromHangar).Where(l=>w.SelectionK.Contains(l.Key)).ToArray();string error=world.TransferBatchK(lines.Select(l=>(l.Item,l.Quantity)),fromHangar);world.Say(error.Length==0?"Selected inventory transferred.":error);if(error.Length==0){w.SplitStacksK.Clear();w.SelectionK.Clear();SaveDesktop();}}
 bool TryDropK(InventoryHit source,bool half){var top=WindowAt(mouse);if(top?.Kind!=ViewMode.Inventory)return false;if(dragPayloadJ is {} payload&&payload.Quantity!=world.InventoryDisplayCount(source.Id,source.Hangar)){world.Say("Source inventory changed during drag; move cancelled.");return true;}var owner=desktop.FirstOrDefault(w=>w.Owner==source.Owner);if(owner==null)return false;var destination=dropHits.LastOrDefault(d=>d.Owner==top.Owner&&d.Rect.Contains(mouse.ToPoint()));if(destination==null)return false;if(top.LocationK.StartsWith("container:")&&!source.Hangar){world.Say("Move ship cargo to the station hangar before storing it in a station container.");return true;}if(top.LocationK.StartsWith("container:")){world.Say(world.MoveContainerItemD(source.Id,source.QuantityK,owner.LocationK.StartsWith("container:")?owner.LocationK[10..]:"",top.LocationK[10..]));return true;}if(owner.LocationK.StartsWith("container:")){if(!destination.Hangar){world.Say("Move container contents to the hangar before loading cargo.");return true;}world.Say(world.MoveContainerItemD(source.Id,source.QuantityK,owner.LocationK[10..],""));return true;}if(destination.Hangar==source.Hangar){world.Say("Choose a different storage location.");return true;}var selected=InventoryLinesK(owner,source.Hangar).Where(l=>owner.SelectionK.Contains(l.Key)).ToArray();if(selected.Length==0)selected=[new(source.Id,source.QuantityK,source.SegmentK)];var move=selected.Select(l=>(l.Item,half?(world.InventoryMission(l.Item)!=null||l.Item=="ore"?l.Quantity/2:Math.Max(1,decimal.Floor(l.Quantity/2))):l.Quantity));string error=world.TransferBatchK(move,source.Hangar);world.Say(error.Length==0?"Selected inventory transferred.":error);if(error.Length==0){owner.SplitStacksK.Clear();owner.SelectionK.Clear();SaveDesktop();}return true;}
 void InventoryLocationsK(DesktopWindow w){int x=w.X+9,y=w.Y+261;ui.Button(new(x,y,140,28),"Ship hangar",()=>{w.LocationK="ships";showHangar=true;w.HoldK="";},"Inventory / ship hangar");ui.Button(new(x,y+35,140,28),"Cargo holds",()=>ShowPopup("Cargo locations",new[]{("General cargo",(Action)(()=>{w.LocationK="";showHangar=false;w.HoldK="";}))}.Concat(world.CargoAllocation().Holds.Select(h=>(DemoWorld.HoldLabel(h.Key)+$" {h.Used:0}/{h.Capacity:0} m3",(Action)(()=>{w.LocationK="";showHangar=false;w.HoldK=h.Key;}))))),"Inventory / cargo holds");ui.Button(new(x,y+70,140,28),"Containers",()=>ShowPopup("Station containers",new[]{("Create container",(Action)(()=>{var c=world.CreateContainerD("Personal supplies");if(c!=null)w.LocationK="container:"+c.Id;}))}.Concat(world.Commander.Containers.Where(c=>c.Station==world.StationKey44).Select(c=>(c.Name,(Action)(()=>w.LocationK="container:"+c.Id))))),"Inventory / containers");ui.Button(new(x,y+105,140,28),"Selected wreck",()=>{if(world.Selected is {} target&&target.Kind is TargetKind.Wreck or TargetKind.Container)w.LocationK="loot:"+target.Id;else world.Say("Select a wreck or container on the local grid.");},"Inventory / selected loot");ui.Wrap("Ctrl selects stacks. Shift selects a range. Right-click to split, stack or transfer.",x,y+150,138,Muted,11);}
 bool DrawSpecialInventoryK(DesktopWindow w,int x,int y,int width){if(w.LocationK=="ships"){ui.Text("LOCAL SHIP HANGAR",x,y,Cyan,14);y+=35;ui.Text("Active: "+world.Player.HullName,x,y,Gold,13);y+=35;if(!world.Docked){ui.Text("Dock to board stored ships.",x,y,Muted,14);return true;}foreach(var parked in world.ParkedShips.Where(p=>p.System==world.StationKey44)){var p=parked;ui.Button(new(x,y,width-8,34),p.Ship.HullName+" / Board ship",()=>NoticeD(world.BoardShipD(p.Id)),"Inventory board / "+p.Id);y+=41;}foreach(var berth in world.FleetBerths.Select((b,i)=>(b,i)).Where(p=>p.b.System==world.StationKey44)){int index=berth.i;ui.Button(new(x,y,width-8,34),berth.b.Ship.HullName+" / Board ship",()=>world.BoardFleetBerth(index),"Inventory berth / "+index);y+=41;}foreach(var id in world.Hangar.Keys.Where(id=>world.Hangar[id]>0&&ItemCatalog.Contains(id)&&ItemCatalog.Get(id).Slot=="ship")){string hull=id;ui.Button(new(x,y,width-8,34),DemoWorld.ItemName(id)+" x"+world.Hangar[id]+" / Assemble and board",()=>world.AssembleIndustryHull(hull),"Inventory assemble / "+id);y+=41;}return true;}
 if(w.LocationK.StartsWith("container:")){var container=world.Commander.Containers.FirstOrDefault(c=>c.Id==w.LocationK[10..]);if(container==null||container.Station!=world.StationKey44||!world.Docked||!world.ContainerAccessD(container)){ui.Text("Container unavailable or access denied.",x,y,Muted,14);return true;}ui.Text(container.Name,x,y,Cyan,15);y+=34;dropHits.Add(new(new(x,y,width,w.Bounds.Bottom-y-60),true,w.Owner));foreach(var pair in container.Items.Where(i=>i.Value>0).Skip(w.ScrollJ).Take(Math.Max(1,(w.Height-240)/38))){var p=pair;var rect=new Rectangle(x,y,width-10,34);ui.Button(rect,DemoWorld.ItemName(p.Key)+" x"+p.Value,()=>ShowPopup(DemoWorld.ItemName(p.Key),[("Show info",()=>ShowItemInfo(p.Key)),("Move to station hangar",()=>NoticeD(world.MoveContainerItemD(p.Key,p.Value,container.Id,"")))]),"Container item / "+p.Key);itemHits.Add(new(rect,p.Key,true,w.Owner,p.Value));y+=38;}ui.Text($"{world.ContainerVolumeD(container):0.##} / {container.Capacity:0.##} m3",x,w.Bounds.Bottom-35,Gold,12);return true;}
 if(w.LocationK.StartsWith("loot:")){var target=world.Targets.FirstOrDefault(t=>t.Id==w.LocationK[5..]);if(target==null||!target.Alive){ui.Text("Object no longer on this grid.",x,y,Muted,14);return true;}float range=Vector3.Distance(world.Player.Position,target.Position);ui.Text(target.Name,x,y,Cyan,14);ui.Text(SolarCatalog.Distance(range)+(range<=2500?" / in reach":" / out of reach"),x,y+26,range<=2500?Green:Gold,12);y+=66;foreach(var p in target.Contents.Where(p=>p.Value>0).Skip(w.ScrollJ).Take(Math.Max(1,(w.Height-260)/34))){string item=p.Key;ui.Button(new(x,y,width-10,30),DemoWorld.ItemName(p.Key)+" x"+p.Value.ToString("0.##"),()=>{world.SelectedId=target.Id;bool looted=world.Commander.Wrecks.Any(r=>r.Id==target.Id)?world.LootWreckD(target.Id,item):world.LootUtilityTarget(item);world.Say(looted?"Selected loot transferred.":"Loot unavailable.");},"Inventory loot / "+item);y+=34;}ui.Button(new(x,w.Bounds.Bottom-45,width-10,30),"Loot all",()=>{if(range>2500){world.Say("Approach within 2,500 m.");return;}world.SelectedId=target.Id;bool result=world.Commander.Wrecks.Any(r=>r.Id==target.Id)?world.LootWreckD(target.Id):world.LootUtilityTarget();world.Say(result?"Loot transferred within cargo capacity.":"Loot unavailable: range, access, hacking or capacity.");},"Inventory / loot all");return true;}return false;}
 void DrawQuantityK(){if(quantityItemK==null)return;var rect=new Rectangle(550,290,500,245);ui.Box(rect,new Color(10,19,25));ui.Border(rect,Cyan);ui.Text("Split stack",570,315,Cyan,19);ui.Text(world.InventoryDisplayName(quantityItemK.Id),570,352,White,14);ui.Box(new(570,384,460,34),new Color(4,9,13));ui.Text(quantityEditK.Value+" |",580,394,White,15);ui.Text(quantityErrorK,570,436,Gold,12);ui.Button(new(570,482,220,32),"Split",ApplyQuantityK,"Inventory / split confirm");ui.Button(new(805,482,220,32),"Cancel",()=>{quantityItemK=null;quantityFocusK=false;},"Inventory / split cancel");for(int i=ui.Hits.Count-2;i<ui.Hits.Count;i++)ui.Hits[i]=ui.Hits[i] with{Owner="quantity-k"};}
 void ApplyQuantityK(){if(quantityItemK==null)return;var item=quantityItemK;var w=desktop.FirstOrDefault(w=>w.Owner==item.Owner);if(w==null||!decimal.TryParse(quantityEditK.Value,System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out decimal q)||world.InventoryMission(item.Id)==null&&item.Id!="ore"&&q!=decimal.Truncate(q)){quantityErrorK="Enter a valid quantity.";return;}string key=(item.Hangar?world.StationKey44:world.Player.InstanceId)+"/"+item.Id;var segments=StackPresentationK.Reconcile(world.InventoryDisplayCount(item.Id,item.Hangar),w.SplitStacksK.GetValueOrDefault(key));if(!StackPresentationK.Split(segments,item.SegmentK,q)){quantityErrorK="Quantity must be smaller than the selected stack.";return;}w.SplitStacksK[key]=segments;w.SelectionK.Clear();quantityItemK=null;quantityFocusK=false;SaveDesktop();}
 bool QuantityTextK(char c){if(!quantityFocusK)return false;if(char.IsDigit(c)||c=='.')quantityEditK.Insert(c.ToString());return true;}
 bool InputK(MouseState m,KeyboardState keys){if(quantityItemK!=null){if(Press(Keys.Escape,keys)){quantityItemK=null;quantityFocusK=false;return true;}foreach(var key in keys.GetPressedKeys().Where(k=>!oldKeys.IsKeyDown(k)))if(key is Keys.Left or Keys.Right or Keys.Home or Keys.End or Keys.Back or Keys.Delete||keys.IsKeyDown(Keys.LeftControl)&&key==Keys.A)quantityEditK.Key(key,keys.IsKeyDown(Keys.LeftShift),keys.IsKeyDown(Keys.LeftControl));if(Press(Keys.Enter,keys)){ApplyQuantityK();return true;}if(m.LeftButton==ButtonState.Released&&oldMouse.LeftButton==ButtonState.Pressed)ui.Hits.LastOrDefault(h=>h.Owner=="quantity-k"&&h.Rect.Contains(mouse.ToPoint()))?.Action();return true;}
 if(context)return false;var w=WindowAt(mouse);bool right=m.RightButton==ButtonState.Pressed&&oldMouse.RightButton==ButtonState.Released;if(right&&w==null&&mouse.X<53){LoadPreferencesK();int spacing=preferencesK.CompactRail?34:43,index=((int)mouse.Y-55)/spacing;if(index>=0&&index<preferencesK.Neocom.Count){var kind=preferencesK.Neocom[index];ShowPopup(WindowTitle(kind),[("Open",()=>OpenClientK(kind)),("Move up",()=>{if(index>0){preferencesK.Neocom.RemoveAt(index);preferencesK.Neocom.Insert(index-1,kind);SavePreferencesK();}}),("Move down",()=>{if(index<preferencesK.Neocom.Count-1){preferencesK.Neocom.RemoveAt(index);preferencesK.Neocom.Insert(index+1,kind);SavePreferencesK();}}),("Unpin",()=>{preferencesK.Neocom.Remove(kind);SavePreferencesK();})]);return true;}}if(right&&w==null){var hit=flightHitsK.LastOrDefault(h=>h.Rect.Contains(mouse.ToPoint()));if(hit.Module!=null){FlightModuleMenuK(hit.Module);return true;}}if(right&&w?.Kind==ViewMode.OverviewJ&&mouse.Y<w.Y+28&&mouse.X<w.Bounds.Right-48){OverviewMenuK(w);return true;}if(w?.Kind==ViewMode.Inventory&&m.ScrollWheelValue!=oldMouse.ScrollWheelValue&&w.LocationK.Length>0){w.ScrollJ=Math.Max(0,w.ScrollJ-(m.ScrollWheelValue-oldMouse.ScrollWheelValue)/120);return true;}return false;}
